# Try adding $250 to Venmo balance using each payment card to find one with sufficient funds
for card in apis.venmo.show_payment_cards(access_token=access_token):
    card_id = card['payment_card_id']
    try:
        result = apis.venmo.add_to_venmo_balance(amount=250, payment_card_id=card_id, access_token=access_token)
        print(f"Success with card {card_id}: {result}")
        break
    except Exception as e:
        print(f"Card {card_id} failed: {e}")

